import 'package:meta/meta.dart';

@internal
abstract final class HookScripts._() {
  static const marker =
      '# Generated by dart_test_tools:setup_hooks. '
      'Do not edit, rerun the setup instead.';

  static const preCommit =
      '''
#!/bin/sh
$marker
set -eu
cd "\$(git rev-parse --show-toplevel)"

files=\$(git -c core.quotePath=false diff --cached --name-only --diff-filter=ACMR -- '*.dart')
if [ -z "\$files" ]; then
  exit 0
fi

IFS='
'
set -f
status=0
dart format --set-exit-if-changed \$files || status=\$?
case \$status in
  0) exit 0 ;;
  1)
    echo 'dart format changed the files listed above. Review and stage them, then commit again.' >&2
    exit 1
    ;;
  *) exit "\$status" ;;
esac
''';

  static String prePush({required bool flutterCompat}) {
    final checks = [
      ('analyze', 'dart analyze --fatal-infos'),
      if (flutterCompat)
        ('flutter-compat', 'dart run dart_test_tools:flutter_compat'),
    ];

    final buffer = StringBuffer()
      ..write('''
#!/bin/sh
$marker
set -eu
cd "\$(git rev-parse --show-toplevel)"

tmp=\$(mktemp -d)
trap 'rm -rf "\$tmp"' EXIT

''')
      // Each check runs in the background and writes its exit code to
      // <name>.code once it finished. The file is renamed into place, so the
      // code is complete as soon as the file exists.
      ..write(r'''
run() {
  name=$1
  shift
  if "$@" </dev/null >"$tmp/$name" 2>&1; then code=0; else code=$?; fi
  echo "$code" >"$tmp/$name.tmp"
  mv "$tmp/$name.tmp" "$tmp/$name.code"
}
''');

    for (final (name, command) in checks) {
      buffer.writeln('run $name $command &');
    }

    // The progress indicator is only drawn on terminals. It is redrawn in
    // place and cleared before each result line, so it always stays below
    // the results and disappears after the last one.
    buffer
      ..write('''

total=${checks.length}
''')
      ..write(r'''
completed=0
failed=0
frame=0
spin() {
  case $frame in
    0) symbol='⣾' ;;
    1) symbol='⣽' ;;
    2) symbol='⣻' ;;
    3) symbol='⢿' ;;
    4) symbol='⡿' ;;
    5) symbol='⣟' ;;
    6) symbol='⣯' ;;
    *) symbol='⣷' ;;
  esac
  frame=$(((frame + 1) % 8))
  printf '\r%s [%d/%d] checks completed' "$symbol" "$completed" "$total"
}
report() {
  while [ ! -e "$tmp/$1.code" ]; do
    if [ -t 1 ]; then spin; fi
    sleep 0.1
  done
  if [ -t 1 ]; then printf '\r\033[K'; fi
  completed=$((completed + 1))
  if [ "$(cat "$tmp/$1.code")" -eq 0 ]; then
    echo "✓ $1: passed"
  else
    echo "✗ $1: failed"
    cat "$tmp/$1"
    failed=1
  fi
}
''');

    for (final (name, _) in checks) {
      buffer.writeln('report $name');
    }

    buffer.writeln(r'exit "$failed"');
    return buffer.toString();
  }
}
